from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
import itertools

# Load the workbook and select the sheet
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Extract all words from column A (assuming words are in column A)
words = [cell.value for cell in ws['A'][1:] if cell.value is not None]

# Dictionary to store words grouped by their non-'S' letters
groups = {}

for word in words:
    # Create a key where all 'S' characters are removed
    key = ''.join([c for c in word if c != 'S'])
    if key not in groups:
        groups[key] = []
    groups[key].append(word)

# Collect all pairs of words that match the criteria
pairs = []

for group in groups.values():
    # Check all combinations of words in the group
    for w1, w2 in itertools.combinations(group, 2):
        # Check if one word can be transformed into the other by replacing 'S' with a vowel
        if len(w1) != len(w2):
            continue
        is_valid = True
        vowel_map = {}
        for c1, c2 in zip(w1, w2):
            if c1 == c2:
                continue
            if c1 == 'S':
                if c2 not in {'A', 'E', 'I', 'O', 'U'}:
                    is_valid = False
                    break
                vowel_map['S'] = c2
            elif c2 == 'S':
                if c1 not in {'A', 'E', 'I', 'O', 'U'}:
                    is_valid = False
                    break
                vowel_map['S'] = c1
            else:
                is_valid = False
                break
        if is_valid:
            # Ensure the same vowel is used for all 'S' replacements
            if all(c == vowel_map['S'] for c in [c2 if c1 == 'S' else c1 for c1, c2 in zip(w1, w2) if c1 == 'S' or c2 == 'S']):
                pairs.append((w1, w2))

# Remove duplicate pairs (e.g., (w1, w2) and (w2, w1))
unique_pairs = set()
for p in pairs:
    unique_pairs.add(tuple(sorted(p)))

# Convert to a list and sort case-insensitively
sorted_pairs = sorted(unique_pairs, key=lambda x: (x[0].lower(), x[1].lower()))

# Write the sorted pairs to columns G and H starting at G2 and H2
for i, (w1, w2) in enumerate(sorted_pairs, start=1):
    ws[f'G{i+1}'] = w1
    ws[f'H{i+1}'] = w2

# Save the workbook
wb.save('output.xlsx')
