from openpyxl import load_workbook
from openpyxl.styles import Font, Alignment, Border, Side, PatternFill
from openpyxl.utils import get_column_letter
import copy

def merge_rows_based_on_column(file_path, sheet_name, reference_col, output_sheet_name):
    # Load the workbook and select the sheets
    wb = load_workbook(file_path)
    data_sheet = wb[sheet_name]
    combined_sheet = wb[output_sheet_name]

    # Clear the combined sheet
    combined_sheet.delete_rows(1, combined_sheet.max_row)

    # Copy the header row
    for col in range(1, data_sheet.max_column + 1):
        combined_sheet.cell(row=1, column=col, value=data_sheet.cell(row=1, column=col).value)

    # Dictionary to store grouped rows
    grouped_data = {}

    # Iterate through the data rows
    for row in data_sheet.iter_rows(min_row=2, values_only=False):
        key_value = row[reference_col - 1].value
        if key_value not in grouped_data:
            grouped_data[key_value] = {
                'row': [cell.value for cell in row],
                'styles': [copy.copy(cell) for cell in row]
            }
        else:
            # Merge the values for the columns from I to R (columns 9 to 18)
            for i in range(8, 18):  # Columns I to R (0-based index 8 to 17)
                existing_value = grouped_data[key_value]['row'][i]
                new_value = row[i].value
                if existing_value is None:
                    grouped_data[key_value]['row'][i] = new_value
                elif new_value is not None:
                    # If both values are not None, sum them
                    if isinstance(existing_value, (int, float)) and isinstance(new_value, (int, float)):
                        grouped_data[key_value]['row'][i] = existing_value + new_value
                    else:
                        # If values are not numeric, keep the existing one
                        grouped_data[key_value]['row'][i] = existing_value

    # Write the grouped data to the combined sheet
    for idx, (key, data) in enumerate(grouped_data.items()):
        row_data = data['row']
        for col in range(len(row_data)):
            cell_value = row_data[col]
            if 8 <= col <= 17:  # Columns I to R
                if isinstance(cell_value, (int, float)):
                    # Format with 2 decimals, no commas, and 0s as blanks
                    if cell_value == 0:
                        cell_value = ''
                    else:
                        cell_value = f"{cell_value:.2f}"
                elif cell_value is None:
                    cell_value = ''
            combined_sheet.cell(row=idx + 2, column=col + 1, value=cell_value)

    # Copy formatting from the original data sheet
    for idx, (key, data) in enumerate(grouped_data.items()):
        for col in range(len(data['row'])):
            original_cell = data['styles'][col]
            target_cell = combined_sheet.cell(row=idx + 2, column=col + 1)
            # Copy font
            if original_cell.font:
                target_cell.font = copy.copy(original_cell.font)
            # Copy alignment
            if original_cell.alignment:
                target_cell.alignment = copy.copy(original_cell.alignment)
            # Copy border
            if original_cell.border:
                target_cell.border = copy.copy(original_cell.border)
            # Copy fill
            if original_cell.fill:
                target_cell.fill = copy.copy(original_cell.fill)

    # Save the workbook
    wb.save("output.xlsx")

# Run the function
merge_rows_based_on_column("input.xlsx", "DATA", 8, "combined")
