from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")

# Select the relevant sheets
daily_numbers_sheet = wb["Daily Numbers"]
inbound_receipts_sheet = wb["Inbound Receipts"]

# Define the error codes and users
error_codes = ["II", "IR", "IT", "OV", "PI"]
users = ["CHROGIL1", "CHDSPOLJ", "CHSJEFFE", "CHBTHOMA"]
warehouse = "27"
date = "2021-08-20 00:00:00"

# Initialize the total cartons received and total errors
total_cartons_received = 0
total_errors = 0

# Step 1: Calculate total cartons received for warehouse 27 and date
for row in daily_numbers_sheet.iter_rows(min_row=3, max_row=24, min_col=1, max_col=1):
    whs = row[0].value
    if whs == warehouse:
        # Find the Inbound Receipts column (column L)
        inbound_receipts_col = daily_numbers_sheet["L"]
        for cell in inbound_receipts_col:
            if cell.row >= 3 and cell.row <= 24:
                if daily_numbers_sheet[f"A{cell.row}"].value == warehouse and daily_numbers_sheet[f"K{cell.row}"].value == date:
                    total_cartons_received = cell.value
                    break

# Step 2: Calculate total errors for warehouse 27, date, and specific users
for error_code in error_codes:
    if error_code == "IR":
        # For IR, only include positive numbers
        for row in daily_numbers_sheet.iter_rows(min_row=3, max_row=24, min_col=1, max_col=1):
            whs = row[0].value
            if whs == warehouse:
                # Find the error column (N to R)
                for col_idx, col_letter in enumerate(["N", "O", "P", "Q", "R"], start=1):
                    if daily_numbers_sheet[f"{col_letter}1"].value == error_code:
                        error_col = col_letter
                        break
                # Iterate through the rows and users
                for user in users:
                    for row in daily_numbers_sheet.iter_rows(min_row=3, max_row=24, min_col=1, max_col=1):
                        if daily_numbers_sheet[f"A{row[0].row}"].value == warehouse and daily_numbers_sheet[f"K{row[0].row}"].value == date:
                            error_value = daily_numbers_sheet[f"{error_col}{row[0].row}"].value
                            if error_value is not None and error_value > 0:
                                total_errors += error_value
    else:
        # For other error codes, include all values
        for row in daily_numbers_sheet.iter_rows(min_row=3, max_row=24, min_col=1, max_col=1):
            whs = row[0].value
            if whs == warehouse:
                # Find the error column (N to R)
                for col_idx, col_letter in enumerate(["N", "O", "P", "Q", "R"], start=1):
                    if daily_numbers_sheet[f"{col_letter}1"].value == error_code:
                        error_col = col_letter
                        break
                # Iterate through the rows and users
                for user in users:
                    for row in daily_numbers_sheet.iter_rows(min_row=3, max_row=24, min_col=1, max_col=1):
                        if daily_numbers_sheet[f"A{row[0].row}"].value == warehouse and daily_numbers_sheet[f"K{row[0].row}"].value == date:
                            error_value = daily_numbers_sheet[f"{error_col}{row[0].row}"].value
                            if error_value is not None:
                                total_errors += error_value

# Step 3: Calculate the difference
difference = total_cartons_received - total_errors

# Write the computed value into the answer range
for row in range(3, 25):
    daily_numbers_sheet[f"Q{row}"] = difference

# Save the workbook
wb.save("output.xlsx")
